problem:
Problem description
- The planning horizon is divided into $$K$$ consecutive time periods over a total horizon of $$H$$ hours, with periods indexed by $$t \in \mathcal{T}$$.
- The hospital must staff nurses to meet a required demand level $$d_t$$ in every period $$t$$.
- There are two nurse categories indexed by $$i \in \mathcal{I}$$, where $$\mathcal{I} = \{\mathrm{reg}, \mathrm{con}\}$$, representing regular nurses and contract nurses.
- Allowed shift start batches are indexed by $$s \in \mathcal{S}$$. A nurse assigned to batch $$s$$ starts at time $$\tau_s$$ and works continuously for a shift length of $$L$$ hours.
- Regular nurses and contract nurses have the same shift length and the same coverage behavior; they differ only in hourly labor cost.
- The hourly labor cost for regular nurses is $$c^{\mathrm{reg}}$$, and the hourly labor cost for contract nurses is $$c^{\mathrm{con}}$$.
- The planning goal is to choose how many nurses of each type to start in each allowed batch so that every period’s demand is covered at minimum total labor cost.
- Staffing decisions must be nonnegative integers.
- Every hired nurse must work a full shift once assigned, and a shift may cover one or more adjacent periods depending on the overlap between the shift interval and the planning periods.
- The model should determine whether any contract nurses are used and, if so, how many are hired in total and by start batch.
- A solution is represented by:
  - $$x_{s}^{\mathrm{reg}}$$, the number of regular nurses starting in batch $$s \in \mathcal{S}$$.
  - $$x_{s}^{\mathrm{con}}$$, the number of contract nurses starting in batch $$s \in \mathcal{S}$$.
  - $$y^{\mathrm{con}}$$, a binary indicator showing whether contract nurses are used at all.
  - $$X^{\mathrm{reg}}$$, the total number of regular nurses hired across all batches.
  - $$X^{\mathrm{con}}$$, the total number of contract nurses hired across all batches.
  - $$Z$$, the total labor cost of the staffing plan.

Input Format
{
  "time_horizon": {
    "type": "integer",
    "meaning": "Total planning horizon $$H$$ in hours."
  },
  "periods": {
    "type": "array",
    "length": "$$K$$",
    "meaning": "Ordered planning periods indexed by $$t \in \mathcal{T}$$.",
    "items": {
      "start_time": "string",
      "end_time": "string",
      "demand": "integer; required nurse count $$d_t$$ for period $$t$$."
    }
  },
  "shift_starts": {
    "type": "array",
    "length": "$$S$$",
    "meaning": "Allowed shift start times $$\\tau_s$$ indexed by $$s \\in \\mathcal{S}$$."
  },
  "shift_duration": {
    "type": "number",
    "meaning": "Shift length $$L$$ in hours."
  },
  "nurse_types": {
    "type": "object",
    "meaning": "Nurse categories $$\\mathcal{I} = \\{\\mathrm{reg}, \\mathrm{con}\\}$$.",
    "fields": {
      "regular": {
        "hourly_cost": "number; regular nurse hourly cost $$c^{\\mathrm{reg}}$$."
      },
      "contract": {
        "hourly_cost": "number; contract nurse hourly cost $$c^{\\mathrm{con}}$$."
      }
    }
  },
  "coverage_rule": {
    "type": "string",
    "meaning": "Describes how a shift starting at $$\\tau_s$$ and lasting $$L$$ hours covers the planning periods; the derived coverage indicator may be represented by $$a_{t,s}$$."
  }
}

Output Format
{
  "hire_plan": {
    "regular_by_start": {
      "type": "array",
      "length": "$$S$$",
      "meaning": "Values $$x_s^{\\mathrm{reg}}$$ for each shift-start batch $$s \\in \\mathcal{S}$$."
    },
    "contract_by_start": {
      "type": "array",
      "length": "$$S$$",
      "meaning": "Values $$x_s^{\\mathrm{con}}$$ for each shift-start batch $$s \\in \\mathcal{S}$$."
    },
    "use_contract_nurses": {
      "type": "boolean",
      "meaning": "Indicator $$y^{\\mathrm{con}}$$ showing whether any contract nurses are hired."
    }
  },
  "summary": {
    "total_regular_hires": {
      "type": "integer",
      "meaning": "Total regular nurses hired, $$X^{\\mathrm{reg}}$$."
    },
    "total_contract_hires": {
      "type": "integer",
      "meaning": "Total contract nurses hired, $$X^{\\mathrm{con}}$$."
    },
    "total_labor_cost": {
      "type": "number",
      "meaning": "Objective value $$Z$$."
    }
  }
}

